def word_frequency(text):
    d = {}
    for w in text.split():
        d[w] = d.get(w, 0) + 1
    return d

def election_winner(votes):
    counts = {}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    best = max(counts.values())
    cands = [k for k, c in counts.items() if c == best]
    return min(cands)

def oxford_join_semicolon(items):
    sep = ";" if any("," in i for i in items) else ","
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    joiner = sep + " "
    return joiner.join(items[:-1]) + f"{sep} and {items[-1]}"

def remove_kth_char(s, k):
    if 0 <= k < len(s):
        return s[:k] + s[k+1:]
    return s

def count_matching_digit_positions(a, b):
    sa, sb = str(a), str(b)
    length = max(len(sa), len(sb))
    sa = sa.zfill(length)
    sb = sb.zfill(length)
    return sum(1 for x, y in zip(sa, sb) if x == y)

def total_days_in_months_range(year, month1, month2):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    return sum(lengths[month1-1:month2])

def last_weekday_of_month(year, month, weekday_num):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def wd(y, m, d):
        if m < 3:
            m += 12
            y -= 1
        K = y % 100
        J = y // 100
        h = (d + (13 * (m + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
        return (h + 5) % 7
    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    last_wd = wd(year, month, dim)
    diff = (last_wd - weekday_num) % 7
    return dim - diff

def split_by_parity_runs(lst):
    res = []
    for x in lst:
        if res and (res[-1][-1] % 2) == (x % 2):
            res[-1].append(x)
        else:
            res.append([x])
    return res

def union_preserve_order(a, b):
    seen = set()
    out = []
    for x in a + b:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def to_snake_case(s):
    result = []
    for i, c in enumerate(s):
        if c.isupper():
            if i != 0:
                result.append('_')
            result.append(c.lower())
        else:
            result.append(c)
    return "".join(result)

def is_valid_e164_phone_number(s):
    if not s.startswith('+'):
        return False
    digits = s[1:]
    if not digits.isdigit():
        return False
    if not (8 <= len(digits) <= 15):
        return False
    return digits[0] != '0'

def wrap_count_lines(text, width):
    words = text.split()
    if not words:
        return 0
    lines = 1
    cur_len = len(words[0])
    for word in words[1:]:
        if cur_len + 1 + len(word) <= width:
            cur_len += 1 + len(word)
        else:
            lines += 1
            cur_len = len(word)
    return lines

def is_acronym_match(acronym, phrase):
    words = phrase.split()
    if len(words) != len(acronym):
        return False
    return all(w[0].lower() == a.lower() for w, a in zip(words, acronym))

def is_product_palindrome(a, b):
    s = str(a * b)
    return s == s[::-1]

def is_valid_hex_color_full(s):
    if len(s) != 7 or s[0] != '#':
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(c in hexdigits for c in s[1:])

def lcm_two(a, b):
    if a == 0 or b == 0:
        return 0
    a, b = abs(a), abs(b)
    x, y = a, b
    while y:
        x, y = y, x % y
    return a // x * b

def capitalize_after_delimiter(s, delim):
    result = list(s)
    capitalize_next = False
    for i, c in enumerate(result):
        if capitalize_next and c.isalpha():
            result[i] = c.upper()
            capitalize_next = False
        if c == delim:
            capitalize_next = True
    return "".join(result)

def longest_alternating_run(lst):
    n = len(lst)
    if n == 0:
        return 0
    best = 1
    cur = 1
    prev_dir = 0
    for i in range(1, n):
        if lst[i] > lst[i - 1]:
            d = 1
        elif lst[i] < lst[i - 1]:
            d = -1
        else:
            d = 0
        if d == 0:
            cur = 1
            prev_dir = 0
        elif d == prev_dir:
            cur = 2
            prev_dir = d
        else:
            cur += 1
            prev_dir = d
        best = max(best, cur)
    return best

def count_full_weekends_in_range(start_day_num, end_day_num):
    count = 0
    for d in range(start_day_num, end_day_num):
        if d % 7 == 5 and d + 1 <= end_day_num and (d + 1) % 7 == 6:
            count += 1
    return count

def hms_to_seconds_signed(s):
    sign = -1 if s.startswith("-") else 1
    s = s.lstrip("-")
    h, m, sec = s.split(":")
    return sign * (int(h) * 3600 + int(m) * 60 + int(sec))

def sort_words_by_vowel_count(words):
    vowels = set("aeiouAEIOU")
    return sorted(words, key=lambda w: (sum(1 for ch in w if ch in vowels), w))

