        return False
    return (any(c.isupper() for c in s) and any(c.islower() for c in s)
            and any(c.isdigit() for c in s))

def proper_divisors(n):
    n = abs(n)
    return [i for i in range(1, n) if n % i == 0]

def is_pandigital(n):
    s = str(n)
    return len(s) == 9 and set(s) == set('123456789')

def count_elements_greater_than_average(lst):
    avg = sum(lst) / len(lst)
    return sum(1 for x in lst if x > avg)

def count_goldbach_pairs(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    for p in range(2, n // 2 + 1):
        if is_prime(p) and is_prime(n - p):
            count += 1
    return count

def is_palindrome_identifier(s):
    if not s or not s.isalnum():
        return False
    lowered = s.lower()
    return lowered == lowered[::-1]

def is_valid_simple_html_tags(s):
    import re
    tokens = re.findall(r'<[a-z]>|</[a-z]>', s)
    if len(''.join(tokens)) != len(s):
        return False
    stack = []
    for tok in tokens:
        if tok.startswith('</'):
            letter = tok[2]
            if not stack or stack.pop() != letter:
                return False
        else:
            stack.append(tok[1])
    return not stack

def leaderboard_rank_by_name_tiebreak(entries):
    scores_sorted = sorted({score for name, score in entries}, reverse=True)
    rank_map = {score: i + 1 for i, score in enumerate(scores_sorted)}
    return {name: rank_map[score] for name, score in entries}

def is_geometric_sequence(lst):
    n = len(lst)
    if n <= 1:
        return True
    ratio = lst[1] / lst[0]
    for i in range(1, n):
        if lst[i] / lst[i - 1] != ratio:
            return False
    return True
